"""Clothing vocabulary, part B: the clth_* descriptive files and the garment lists (outfit_*).  All new options are colour-free
(colours come from outfit_color) and avoid age/gender wording except where the list itself is gendered (f_/m_ garment lists)."""
import random, itertools
from vocab_lib import S, sample, product, merge, seed_of
import vocab_clothing_a as A

# ------------------------------------------------------------------ generic composers
def garment_variants(garments, mods, details, n, name):
    """plain garment, 'mod garment', 'garment with detail' and 'mod garment with detail' - sampled evenly"""
    out = list(garments)
    out += [f'{m} {g}' for g in garments for m in mods]
    out += [f'{g} with {d}' for g in garments for d in details]
    rng = random.Random(seed_of(name))
    trio = [f'{m} {g} with {d}' for g in garments for m in mods for d in details]
    rng.shuffle(trio)
    out += trio[: max(0, n * 2)]
    def ok(p):
        w = [x.strip(',').lower() for x in p.split() if len(x) > 3]
        return len(w) == len(set(w))          # no repeated words ("satin satin chemise")
    out = [o for o in out if ok(o)]
    return sample(out, n, name)

