def clth_detail(orig):
    out = product('{0} {1} {2}', FADJ, FASTENERS, FPLACE)
    out = sample(out, 140, 'cd1')
    out += sample(product('{0} {1}', TRIMS, TPLACE), 120, 'cd2')
    out += CONSTRUCTION + DET_EXTRA
    return sample(out, 480, 'cdf')

LIGHT_M = ('chiffon', 'organza', 'tulle', 'voile', 'gauze', 'lace', 'georgette', 'batiste', 'lawn', 'muslin', 'net', 'mesh', 'habotai', 'crepe de chine', 'cheesecloth', 'eyelet', 'broderie', 'silk charmeuse', 'fishnet')
HEAVY_M = ('canvas', 'tweed', 'denim', 'leather', 'felt', 'fleece', 'melton', 'corduroy', 'boiled wool', 'shearling', 'faux fur', 'sherpa', 'tarpaulin', 'burlap', 'hessian', 'duck', 'oilskin', 'oilcloth', 'moleskin', 'flannel', 'wool bouclé', 'harris', 'down', 'puffer', 'insulated', 'neoprene', 'latex', 'rubber', 'ballistic', 'cordura', 'suede', 'nubuck', 'drill', 'whipcord', 'barathea', 'serge')
W_LIGHT = S("featherlight, lightweight, airy, delicate, gossamer-thin, breezy, fine")
W_HEAVY = S("heavyweight, thick, dense, substantial, hefty, rugged, sturdy")
W_MID = S("midweight, medium-weight, supple, well-draped, firm, tightly woven, loosely woven, soft-handled, crisp")
FINISH = S("matte, lustrous, softly brushed, stonewashed, garment-washed, textured, smooth, lightly crinkled, slightly sheer, fully opaque, pre-worn, subtly stretchy, slubbed, ribbed, flat-woven, glossy, waxed, sand-washed, napped, pilled and well-loved")
def fabric_phrase(m, rng):
    ml = m.lower()
    pool = W_LIGHT if any(k in ml for k in LIGHT_M) else W_HEAVY if any(k in ml for k in HEAVY_M) else W_MID
    f = rng.choice(FINISH)
    return f'{rng.choice(pool)} {f} {m} fabric'
def clth_fabric(orig):
    rng = random.Random(seed_of('cf')); out = []
    mats = A.MATERIALS
    for m in mats:
        out.append(f'{m} fabric'); out.append(fabric_phrase(m, rng))
    for m in mats: out.append(fabric_phrase(m, rng))
    # skip finishes that contradict their fabric (e.g. a sheer lace "fully opaque")
    out = [o for o in out if not (('fully opaque' in o) and any(k in o for k in LIGHT_M)) and not (('slightly sheer' in o) and any(k in o for k in HEAVY_M))]
    return sample(out, 480, 'cff')

FIT_WORDS = S("loose, relaxed, fitted, snug, tailored, oversized, cropped, elongated, boxy, tapered, flared, billowing, draped, structured, slouchy, streamlined, voluminous, body-skimming, close-cut, sculpted, easy, generous, trim, straight, curved, A-line, balloon, barrel, column, wrapped, gathered")
FIT_PART = S("through the body, through the shoulders, at the waist, through the hips, in the sleeves, in the legs, at the hem, across the chest, from shoulder to hem, through the torso, around the thighs, at the ankles, at the cuffs, through the seat")
FIT_DEG = S("slightly, very, effortlessly, deliberately, comfortably, a little, extremely, noticeably")
FIT_WHOLE = S("impeccably tailored custom fit, off-the-rack fit that is a touch too big, hand-me-down fit that is too roomy, borrowed oversized fit, shrunk-in-the-wash snug fit, comfortable everyday fit, athletic cut with room to move, classic straight cut, modern slim cut, heritage relaxed cut, high-fashion exaggerated silhouette, architectural silhouette, soft flowing silhouette, retro nipped-waist silhouette, 90s baggy silhouette, 70s flared silhouette, 80s power-shoulder silhouette, 60s shift silhouette, 50s full-skirted silhouette, 40s structured silhouette, 20s dropped-waist silhouette, minimal clean-lined silhouette, layered volume silhouette, pared-back everyday fit, dressed-up polished fit, workwear fit with room at the knees and elbows, travel-friendly relaxed fit, one-size-fits-all drape, made-to-measure precision fit")
def clth_fit(orig):
    out = product('{0} {1} {2}', FIT_DEG, FIT_WORDS, FIT_PART)
    out = sample(out, 330, 'fit1') + FIT_WHOLE + [f'{w} fit {p}' for w in FIT_WORDS for p in FIT_PART][:140]
    return sample(out, 480, 'fitf')

L_BASE = S("a plain tee, a tank top, a camisole, a fine-knit top, a thermal base layer, a long-sleeve shirt, a polo shirt, a collared shirt, a sleeveless blouse, a turtleneck, a henley, a bodysuit, a sports bra top, a graphic tee, a muscle tee, a mesh top, a ribbed top, a crop top, a linen shirt, a silk blouse, a vest top, a rugby shirt")
L_MID = S("a cardigan, a sweater, a hoodie, a quarter-zip pullover, a waistcoat, a knitted vest, a flannel shirt, a denim shirt, a fleece, a cropped jumper, a lightweight overshirt, a zip-up track top, a kimono-style robe, a shawl, a sleeveless puffer vest, a gilet, a tailored vest, a chunky knit, a bolero, a shrug")
L_OUT = S("a denim jacket, a leather jacket, a trench coat, a wool overcoat, a parka, a puffer jacket, a bomber jacket, a blazer, a raincoat, a windbreaker, a duster coat, a peacoat, a quilted jacket, a poncho, a cape, a field jacket, a shearling coat, an oversized coat, a utility jacket, a cropped jacket, a varsity jacket, a long cardigan coat, a waxed jacket, a down coat, a kimono jacket, a mac coat, a coach jacket, a safari jacket, a chore coat, a hooded anorak")
L_ACC = S("a long scarf, a chunky scarf, a silk neckerchief, a knitted snood, a shawl draped over the shoulders, fingerless gloves, a belt cinching the outer layer, a bag strap across the chest, a crossbody bag over the coat, a backpack slung on one shoulder, a tied-on sweater around the waist, a jacket knotted at the waist, a shirt tied at the waist, a hood pulled up, a collar turned up, sleeves pushed up, cuffs turned back")
def clth_layers(orig):
    out = [f'{b} under {m} and {o}' for b, m, o in itertools.product(L_BASE, L_MID, L_OUT)]
    out = sample(out, 220, 'ly1')
    out += sample([f'{b} under {o}' for b, o in itertools.product(L_BASE, L_OUT)], 90, 'ly2')
    out += sample([f'{b} with {m}, {a}' for b, m, a in itertools.product(L_BASE, L_MID, L_ACC)], 90, 'ly3')
    out += sample([f'{m} over {b}, worn open' for b, m in itertools.product(L_BASE, L_MID)], 40, 'ly4')
    out += [f'{o}, {a}' for o in L_OUT[:15] for a in L_ACC[:4]][:40]
    return sample(out, 480, 'lyf')

PSCALE = S("bold, subtle, tiny, oversized, faded, repeating, sparse, dense, scattered, tonal, high-contrast, hand-drawn, geometric, loosely spaced, tightly packed, washed-out, vintage-style, modern minimalist, abstract, painterly")
PBASE = [p for p in A.PATTERNS if not p.startswith(('solid', 'plain'))]
def clth_pattern(orig):
    out = [f'{s} {p} pattern' if not p.endswith('print') else f'{s} {p}' for p in PBASE for s in PSCALE]
    out = sample(out, 440, 'cp1') + [f'{p} pattern' if not p.endswith('print') else p for p in PBASE]
    out += S("plain solid fabric with no pattern, clean unpatterned surface, solid block of single tone, tonal self-pattern woven into the cloth, subtle texture only with no print")
    return sample(out, 500, 'cpf')

